  "ИЗБРАНО ДОКАЗАТЕЛСТВО":{en:"SELECTED EVIDENCE",de:"AUSGEWÄHLTER BEWEIS",fr:"PREUVE SÉLECTIONNÉE",pl:"WYBRANY DOWÓD",es:"PRUEBA SELECCIONADA"},
