  "СЦЕНИЧНИ ЕФЕКТИ":{en:"SCENE EFFECTS",de:"SZENENEFFEKTE",fr:"EFFETS DE SCÈNE",pl:"EFEKTY SCENICZNE",es:"EFECTOS DE ESCENA"},
