  "Ирина Петрова":{en:"Irina Petrova",de:"Irina Petrova",fr:"Irina Petrova",pl:"Irina Petrowa",es:"Irina Petrova"},
  "Борис Колев":{en:"Boris Kolev",de:"Boris Kolev",fr:"Boris Kolev",pl:"Boris Kolew",es:"Boris Kolev"},
  "Николай Маринов":{en:"Nikolay Marinov",de:"Nikolai Marinow",fr:"Nikolaï Marinov",pl:"Nikołaj Marinow",es:"Nikolay Marinov"},
  "Мая Димитрова":{en:"Maya Dimitrova",de:"Maja Dimitrowa",fr:"Maya Dimitrova",pl:"Maja Dimitrowa",es:"Maya Dimitrova"},
  "Стефан Попов":{en:"Stefan Popov",de:"Stefan Popow",fr:"Stefan Popov",pl:"Stefan Popow",es:"Stefan Popov"},
